import java.util.NoSuchElementException;

/**
 * A single entry (key/value pair) stored in the hash table.
 *
 * <p>The key is immutable; the value may be updated in place when an existing
 * key is re-inserted.
 */
final class HashEntry {
    final int key;
    int value;

    HashEntry(int key, int value) {
        this.key = key;
        this.value = value;
    }
}

/**
 * A hash map for primitive {@code int} keys and values that resolves collisions
 * by open addressing with linear probing.
 *
 * <p>Deleted slots are marked with a tombstone (distinguished by reference
 * identity, not by a magic key value) so that probe sequences passing through a
 * removed entry are not cut short. The table grows automatically once the
 * fraction of occupied slots crosses {@link #MAX_LOAD_FACTOR}, which both keeps
 * probe sequences short and guarantees that every probe loop terminates at an
 * empty slot.
 *
 * <p>Unlike the original implementation, any {@code int} — including negative
 * values and {@code -1} — is a valid key and value.
 */
class LinearProbingHashMap {
    private static final int DEFAULT_CAPACITY = 16;

    /**
     * Linear probing degrades sharply as the table fills, so it is resized well
     * before it is full. This also ensures at least one slot is always empty,
     * which is what makes the probing loops guaranteed to terminate.
     */
    private static final double MAX_LOAD_FACTOR = 0.5;

    /** Sentinel marking a slot whose entry was removed. Compared by identity. */
    private static final HashEntry TOMBSTONE = new HashEntry(0, 0);

    private HashEntry[] table;
    private int capacity;
    private int size; // number of live entries
    private int used; // live entries + tombstones (i.e. non-empty slots)

    public LinearProbingHashMap() {
        this(DEFAULT_CAPACITY);
    }

    public LinearProbingHashMap(int initialCapacity) {
        if (initialCapacity < 1) {
            throw new IllegalArgumentException(
                "initialCapacity must be positive: " + initialCapacity);
        }
        capacity = initialCapacity;
        table = new HashEntry[capacity];
    }

    private int indexFor(int key) {
        // floorMod keeps the index in [0, capacity) even for negative keys.
        return Math.floorMod(key, capacity);
    }

    /**
     * Inserts the key, or updates the value if the key is already present.
     */
    public void put(int key, int value) {
        if (used + 1 > capacity * MAX_LOAD_FACTOR) {
            resize(capacity * 2);
        }

        int index = indexFor(key);
        int firstTombstone = -1;

        while (table[index] != null) {
            if (table[index] == TOMBSTONE) {
                if (firstTombstone < 0) {
                    firstTombstone = index;
                }
            } else if (table[index].key == key) {
                table[index].value = value; // update in place
                return;
            }
            index = (index + 1) % capacity;
        }

        // Key is absent. Prefer reusing a tombstone over consuming a fresh slot.
        if (firstTombstone >= 0) {
            table[firstTombstone] = new HashEntry(key, value);
        } else {
            table[index] = new HashEntry(key, value);
            used++;
        }
        size++;
    }

    /** Returns the value for {@code key}, or throws if it is not present. */
    public int get(int key) {
        int index = findIndex(key);
        if (index < 0) {
            throw new NoSuchElementException("No mapping for key " + key);
        }
        return table[index].value;
    }

    /** Returns the value for {@code key}, or {@code defaultValue} if absent. */
    public int getOrDefault(int key, int defaultValue) {
        int index = findIndex(key);
        return index < 0 ? defaultValue : table[index].value;
    }

    public boolean containsKey(int key) {
        return findIndex(key) >= 0;
    }

    /**
     * Removes the mapping for {@code key}.
     *
     * @return {@code true} if a mapping was removed, {@code false} if the key
     *         was not present.
     */
    public boolean remove(int key) {
        int index = findIndex(key);
        if (index < 0) {
            return false;
        }
        table[index] = TOMBSTONE; // keep the probe sequence intact
        size--;
        return true;
    }

    /** Returns the index of {@code key}, or {@code -1} if it is not present. */
    private int findIndex(int key) {
        int index = indexFor(key);
        // The load factor guarantees an empty slot, so this loop terminates.
        while (table[index] != null) {
            if (table[index] != TOMBSTONE && table[index].key == key) {
                return index;
            }
            index = (index + 1) % capacity;
        }
        return -1;
    }

    private void resize(int newCapacity) {
        HashEntry[] old = table;
        table = new HashEntry[newCapacity];
        capacity = newCapacity;
        size = 0;
        used = 0;
        for (HashEntry entry : old) {
            if (entry != null && entry != TOMBSTONE) {
                put(entry.key, entry.value);
            }
        }
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public void display() {
        for (HashEntry entry : table) {
            if (entry != null && entry != TOMBSTONE) {
                System.out.println(entry.key + " " + entry.value);
            }
        }
    }

    public static void main(String[] args) {
        LinearProbingHashMap map = new LinearProbingHashMap();
        map.put(1, 1);
        map.put(2, 2);
        map.put(2, 3); // updates the existing key rather than duplicating it
        map.display();
        System.out.println(map.size());
        System.out.println(map.remove(2));
        System.out.println(map.size());
        System.out.println(map.isEmpty());
        System.out.println(map.containsKey(2));
    }
}

